SET sections = $json$[
  {"id":"section-capa","type":"capa","enabled":true,"title":"Capa","content":{"eyebrow":"PROPOSTA COMERCIAL","headline":"i-Ganhei para {{empresa_cliente}}","subheadline":"Solução comercial para gestão inteligente de vendas públicas."}},
  {"id":"section-termo","type":"termo","enabled":true,"title":"Termo de Confidencialidade e Responsabilidade","content":{"body":"Esta proposta foi elaborada pela StartGi com o objetivo de apresentar, de forma institucional e comercial, a estrutura da solução i-Ganhei e suas possibilidades de aplicação no contexto operacional de vendas públicas. As informações contidas neste material possuem caráter confidencial e destinam-se exclusivamente à análise interna da empresa destinatária, não sendo recomendada sua reprodução, compartilhamento ou utilização para finalidades distintas da avaliação da proposta apresentada, sem prévia autorização da StartGi. Os conceitos, direcionamentos, estruturas operacionais, fluxos, metodologias, nomenclaturas e demais elementos relacionados às soluções e serviços apresentados permanecem vinculados à propriedade intelectual e comercial da StartGi. As características, funcionalidades, etapas de implantação e demais aspectos relacionados à solução poderão ser ajustados conforme o contexto, necessidades e particularidades operacionais de cada cliente, respeitando o escopo comercial posteriormente definido entre as partes. Este documento possui caráter exclusivamente comercial e institucional, tendo como finalidade apoiar a análise da solução apresentada, não caracterizando obrigação de contratação até eventual formalização contratual entre as partes."}},
  {"id":"section-startgi","type":"cards","enabled":true,"title":"1. A StartGi","content":{"intro":"Especialistas em soluções para o mercado de vendas públicas, apoiando empresas que desejam ampliar sua atuação junto ao governo com organização, inteligência estratégica e eficiência operacional.","cards":[{"icon":"Building2","title":"Expertise no setor público","text":"Experiência prática e profundo conhecimento da dinâmica do mercado licitatório brasileiro."},{"icon":"Layers","title":"Ecossistema de soluções","text":"Portfólio estruturado para gestão, acompanhamento e potencialização de oportunidades em vendas públicas."},{"icon":"Handshake","title":"Parceria estratégica","text":"Mais do que tecnologia, atuamos como parceiros para decisões mais rápidas e uma atuação comercial mais competitiva."}]}},
  {"id":"section-contexto","type":"cards","enabled":true,"title":"2. Contexto e Desafios do Cliente","content":{"intro":"O mercado de vendas públicas exige velocidade, organização e alto nível de controle. Sem centralização, a operação perde oportunidades, sofre com retrabalho e perde visibilidade gerencial.","cards":[{"icon":"Search","title":"Identificar oportunidades","text":"Localizar e interpretar editais relevantes em meio a um volume crescente de publicações."},{"icon":"Clock","title":"Acompanhar prazos","text":"Monitorar etapas, datas e responsáveis sem deixar processos críticos escaparem."},{"icon":"BarChart3","title":"Decisões com dados","text":"Transformar informações dispersas em decisões comerciais consistentes e estratégicas."}]}},
  {"id":"section-objetivos","type":"list","enabled":true,"title":"3. Objetivos da Solução","content":{"intro":"Ampliar a eficiência da operação de vendas públicas, reduzindo esforços manuais e aumentando a capacidade de acompanhamento estratégico.","items":[{"icon":"Database","title":"Centralizar informações","text":"Reunir em um único ambiente os dados relevantes da operação licitatória."},{"icon":"Radar","title":"Identificar e acompanhar oportunidades","text":"Melhorar a captação e o monitoramento de editais com fit estratégico."},{"icon":"FileSearch","title":"Análise e priorização de editais","text":"Apoiar a leitura e a tomada de decisão sobre quais processos disputar."},{"icon":"FolderKanban","title":"Organização operacional","text":"Estruturar documentos, prazos, etapas e responsáveis em um único fluxo."},{"icon":"Zap","title":"Produtividade da equipe","text":"Reduzir retrabalho e aumentar a capacidade de execução do time."},{"icon":"LineChart","title":"Visibilidade gerencial","text":"Gerar indicadores sobre pipeline, andamento e resultados da operação."}]}},
  {"id":"section-sobre-iganhei","type":"list","enabled":true,"title":"4. Sobre o i-Ganhei","content":{"intro":"Solução da StartGi para a gestão estratégica de vendas públicas — captação de oportunidades, gestão de processos, organização documental e acompanhamento de resultados em uma única operação.","items":[{"icon":"Compass","title":"Controle da jornada licitatória","text":"Visibilidade ponta a ponta sobre cada oportunidade e suas etapas."},{"icon":"Activity","title":"Agilidade no dia a dia","text":"Mais eficiência operacional na condução das atividades comerciais."},{"icon":"BrainCircuit","title":"Inteligência comercial","text":"Ampliação da capacidade de análise e redução de esforços operacionais."},{"icon":"Trophy","title":"Competitividade no mercado público","text":"Atuação mais organizada, produtiva e orientada à tomada de decisão."}]}},
  {"id":"section-estrutura","type":"cards","enabled":true,"title":"5. Estrutura Operacional da Solução","content":{"intro":"Estrutura flexível e adaptável, direcionada conforme necessidades, prioridades e particularidades de cada operação em vendas públicas.","cards":[{"icon":"Workflow","title":"Jornada comercial","text":"Apoio às diferentes etapas do processo comercial e operacional do cliente."},{"icon":"Database","title":"Centralização","text":"Informações operacionais, documentais e gerenciais reunidas em um único ambiente."},{"icon":"TrendingUp","title":"Decisão estratégica","text":"Visibilidade gerencial e melhoria contínua da atuação no mercado público."}]}},
  {"id":"section-beneficios","type":"benefits","enabled":true,"title":"6. Benefícios Esperados","content":{"items":[{"title":"Mais produtividade","text":"Redução de atividades operacionais repetitivas na rotina de vendas públicas."},{"title":"Melhor aproveitamento de oportunidades","text":"Agilidade no acompanhamento de processos e etapas licitatórias."},{"title":"Centralização das informações","text":"Dados operacionais, documentais e gerenciais organizados em um único lugar."},{"title":"Controle de prazos e responsáveis","text":"Mais governança sobre histórico de atuação e fluxo das informações."},{"title":"Visibilidade de indicadores","text":"Acompanhamento estratégico de resultados e da operação."},{"title":"Decisões baseadas em dados","text":"Apoio comercial com acompanhamento recorrente e inteligência operacional."},{"title":"Operação previsível","text":"Estruturação eficiente para mais previsibilidade e competitividade."},{"title":"Solução adaptável","text":"Configurável às características e ao modelo operacional de cada cliente."}]}},
  {"id":"section-implantacao","type":"timeline","enabled":true,"title":"7. Implantação e Acompanhamento","content":{"intro":"Implementação estruturada e alinhada às características operacionais do cliente, com adaptação gradual e acompanhada pela equipe StartGi.","steps":[{"title":"Alinhamento Inicial","text":"Alinhamento dos objetivos, escopo do projeto e direcionamentos iniciais."},{"title":"Levantamento Operacional","text":"Entendimento do cenário, processos, necessidades e informações relevantes para a estruturação da solução."},{"title":"Estruturação da Solução","text":"Configurações, ajustes e parametrizações conforme o modelo operacional definido para o cliente."},{"title":"Orientação das Equipes","text":"Apresentação da solução, orientação das equipes e preparação para utilização na rotina."},{"title":"Entrada em Operação","text":"Acompanhamento inicial da operação e suporte para assegurar uma experiência eficiente."}]}},
  {"id":"section-investimento","type":"pricing","enabled":true,"title":"8. Investimento","content":{"intro":"Composição comercial com etapa inicial de implantação e mensalidade recorrente pela utilização da plataforma i-Ganhei.","cards":[{"label":"Implantação da Solução (Setup)","value_key":"valor_implantacao","note":"Valor único referente às etapas iniciais de estruturação, alinhamentos operacionais, parametrizações e entrada em operação. Pagamento único."},{"label":"Plataforma i-Ganhei (Mensalidade)","value_key":"valor_mensalidade","note":"Valor mensal referente à disponibilização da plataforma e utilização recorrente da solução.","monthly":true}]}},
  {"id":"section-validade","type":"validade","enabled":true,"title":"9. Validade da Proposta","content":{"body":"Esta proposta possui validade de {{validade_proposta}} dias corridos a partir da data de envio ({{data_proposta}}). Vigência inicial: {{vigencia_inicial}}. Forma de pagamento: {{forma_pagamento}}."}},
  {"id":"section-consideracoes","type":"final","enabled":true,"title":"10. Considerações Finais","content":{"headline":"À disposição para os próximos passos","body":"A StartGi permanece à disposição para esclarecimentos adicionais, assim como para alinhamentos necessários relacionados à presente proposta. Atenciosamente, {{nome_vendedor}}.","next_steps":["Validação interna da proposta por {{empresa_cliente}}","Reunião de aprofundamento e ajustes finais","Formalização contratual entre as partes","Kick-off e início da implantação"]}}
